    "solution": "import java.util.List;\nimport java.util.ArrayList;\nimport java.util.Map;\nimport java.util.LinkedHashMap;\nimport java.util.Set;\nimport java.util.LinkedHashSet;\n\nclass ShippingAddress {\n    private String street;\n    private String city;\n    public ShippingAddress(String street, String city) {\n        this.street = street;\n        this.city = city;\n    }\n    public String getStreet() { return street; }\n    public String getCity() { return city; }\n}\n\nclass Customer {\n    private String name;\n    private double accountBalance;\n    private ShippingAddress shippingAddress;\n    private Map<String, ShippingAddress> deliveryAddresses = new LinkedHashMap<>();\n    public Customer(String name, double balance, ShippingAddress addr) {\n        this.name = name;\n        this.accountBalance = balance;\n        this.shippingAddress = addr;\n    }\n    public String getName() { return name; }\n    public double getAccountBalance() { return accountBalance; }\n    public void setAccountBalance(double b) { this.accountBalance = b; }\n    public ShippingAddress getShippingAddress() { return shippingAddress; }\n    public void addDeliveryAddress(String label, ShippingAddress a) { deliveryAddresses.put(label, a); }\n    public boolean useDeliveryAddress(String label) {\n        ShippingAddress a = deliveryAddresses.get(label);\n        if (a != null) { this.shippingAddress = a; return true; }\n        return false;\n    }\n    public Set<String> getAddressLabels() { return new LinkedHashSet<>(deliveryAddresses.keySet()); }\n    public Map<String, ShippingAddress> getDeliveryAddresses() { return deliveryAddresses; }\n}\n\nclass Product {\n    private String name;\n    private double price;\n    public Product(String name, double price) { this.name = name; this.price = price; }\n    public String getName() { return name; }\n    public double getPrice() { return price; }\n    public double getPriceWithTax() { return Math.round(price * 1.12 * 100.0) / 100.0; }\n    public double calculateDeliveryCost() { return 10000.0; }\n}\n\nclass PhysicalProduct extends Product {\n    private double weightKg;\n    private boolean fragile;\n    public PhysicalProduct(String name, double price, double weightKg, boolean fragile) {\n        super(name, price);\n        this.weightKg = weightKg;\n        this.fragile = fragile;\n    }\n    @Override\n    public double calculateDeliveryCost() {\n        double base = 15000.0;\n        if (weightKg > 10.0) base += 10000.0;\n        if (fragile) base += 10000.0;\n        return base;\n    }\n}\n\nclass ElectronicDevice extends PhysicalProduct {\n    private String brand;\n    private int warrantyMonths;\n    public ElectronicDevice(String name, double price, double weightKg, boolean fragile, String brand, int warranty) {\n        super(name, price, weightKg, fragile);\n        this.brand = brand;\n        this.warrantyMonths = warranty;\n    }\n    @Override\n    public double calculateDeliveryCost() {\n        return super.calculateDeliveryCost() + 20000.0; // insurance\n    }\n}\n\nclass Clothing extends PhysicalProduct {\n    private String size; private String material;\n    public Clothing(String name, double price, double weightKg, boolean fragile, String size, String material) {\n        super(name, price, weightKg, fragile);\n        this.size = size;\n        this.material = material;\n    }\n    public String getSize() { return size; }\n    @Override\n    public double calculateDeliveryCost() { return 20000.0; }\n}\n\nclass DigitalProduct extends Product {\n    private double fileSizeMb;\n    private String downloadUrl;\n    public DigitalProduct(String name, double price, double sizeMb, String url) {\n        super(name, price);\n        this.fileSizeMb = sizeMb;\n        this.downloadUrl = url;\n    }\n    public double estimateDownloadSeconds(double speedMbps) {\n        return Math.round((fileSizeMb * 8.0 / speedMbps) * 10.0) / 10.0;\n    }\n    @Override\n    public double calculateDeliveryCost() { return 0.0; }\n}\n\nclass EBook extends DigitalProduct {\n    private String author; private int pageCount; private String format;\n    public EBook(String name, double price, double sizeMb, String url, String author, int pages, String format) {\n        super(name, price, sizeMb, url);\n        this.author = author;\n        this.pageCount = pages;\n        this.format = format;\n    }\n    public String getAuthor() { return author; }\n    public String getFormat() { return format; }\n}\n\nclass SoftwareLicense extends DigitalProduct {\n    private String licenseKey; private int durationMonths; private int maxDevices;\n    public SoftwareLicense(String name, double price, double sizeMb, String url, String key, int duration, int devices) {\n        super(name, price, sizeMb, url);\n        this.licenseKey = key;\n        this.durationMonths = duration;\n        this.maxDevices = devices;\n    }\n    public String getLicenseDetails() {\n        return \"Litsenziya: \" + licenseKey + \" | Muddat: \" + durationMonths + \" oy | Qurilmalar: \" + maxDevices;\n    }\n}\n\nclass OrderItem {\n    private Product product;\n    private int quantity;\n    public OrderItem(Product product, int quantity) {\n        this.product = product;\n        this.quantity = quantity;\n    }\n    public Product getProduct() { return product; }\n    public int getQuantity() { return quantity; }\n    public double getLineTotal() {\n        return Math.round(product.getPriceWithTax() * quantity * 100.0) / 100.0;\n    }\n}\n\nclass Order {\n    private String orderId;\n    private Customer customer;\n    private List<OrderItem> items = new ArrayList<>();\n    public Order(String orderId) { this.orderId = orderId; }\n    public Order(String orderId, Customer customer) { this.orderId = orderId; this.customer = customer; }\n    public String getOrderId() { return orderId; }\n    public Customer getCustomer() { return customer; }\n    public void addItem(Product p, int qty) {\n        if (qty > 0) items.add(new OrderItem(p, qty));\n    }\n    public double getItemsTotal() {\n        double sum = 0;\n        for (OrderItem it : items) sum += it.getLineTotal();\n        return Math.round(sum * 100.0) / 100.0;\n    }\n    public double getDeliveryCost() {\n        double cost = 0;\n        for (OrderItem it : items) cost += it.getProduct().calculateDeliveryCost();\n        return Math.round(cost * 100.0) / 100.0;\n    }\n    public double calculateTotal() { return getItemsTotal(); }\n    public double getTotal() { return Math.round((getItemsTotal() + getDeliveryCost()) * 100.0) / 100.0; }\n    public void place() {\n        double total = getTotal();\n        if (customer != null) customer.setAccountBalance(customer.getAccountBalance() - total);\n    }\n    public void printSummary() {\n        System.out.println(\"Order \" + orderId + \" for \" + (customer != null ? customer.getName() : \"Guest\") + \" | Total: \" + getTotal());\n    }\n}\n\nclass Main {\n    public static void main(String[] args) {\n        Clothing shirt = new Clothing(\"Ko'ylak\", 180000.0, 0.3, false, \"M\", \"Paxta\");\n        System.out.println(\"Kiyim: \" + shirt.getName() + \" | Yetkazish: \" + shirt.calculateDeliveryCost());\n    }\n}",
